package glitch

import data.glitch_lib

# Weak encryption algorithms
weak_algorithms = {"DES", "3DES", "RC4", "RC2", "Blowfish", "MD5", "SHA1"}

# Weak TLS/SSL versions
weak_tls_versions = {"SSLv2", "SSLv3", "TLSv1", "TLSv1.0", "TLSv1.1", "TLS1.0", "TLS1.1"}

# Weak cipher suite patterns
weak_cipher_patterns = {"DES", "RC4", "NULL", "EXPORT", "anon"}

# Weak key size thresholds by algorithm type (minimum safe sizes)
weak_key_patterns = {"512", "768", "1024", "128"}

# Weak SSL mode settings
weak_ssl_modes = {"disabled", "preferred", "optional", "false"}

# Keywords for encryption-related attributes
encryption_key_keywords = {"algorithm", "encryption_type", "cipher", "crypto", "cryptographic", "symmetric", "asymmetric"}
key_size_keywords = {"key_size", "key_length", "bits", "modulus", "key_bits", "rsa_key_size", "key_length_bits"}
tls_version_keywords = {"tls_version", "ssl_version", "min_version", "protocol_version", "security_policy", "policy"}
cipher_suite_keywords = {"cipher_suite", "ciphers", "allowed_ciphers", "ssl_policy", "policy_name", "tls_policy"}
certificate_keywords = {"certificate", "cert", "private_key", "public_key", "key_algorithm", "signature_algorithm"}
storage_encryption_keywords = {"sse_algorithm", "encryption", "encrypted", "kms_key_id", "server_side_encryption", "storage_encrypted"}
database_encryption_keywords = {"encryption_key", "ssl_mode", "require_ssl", "tls"}
secret_keywords = {"type", "secure_string", "key_id", "data_type"}
network_encryption_keywords = {"phase1_integrity_algorithms", "phase2_encryption_algorithms", "ike_version", "ipsec_policy", "vpn_type"}

# Check if value contains weak algorithm
has_weak_algorithm(value) {
    value.ir_type == "String"
    upper := upper(value.value)
    upper == weak_algorithms[_]
}

# Check if value is weak TLS version
has_weak_tls_version(value) {
    value.ir_type == "String"
    upper_val := upper(replace(replace(replace(value.value, ".", ""), "_", ""), "-", ""))
    upper_val == upper(replace(replace(replace(weak_tls_versions[_], ".", ""), "_", ""), "-", ""))
}

# Check if value contains weak cipher pattern
has_weak_cipher_pattern(value) {
    value.ir_type == "String"
    upper := upper(value.value)
    contains(upper, weak_cipher_patterns[_])
}

# Check if integer value indicates weak key size
has_weak_key_size(value) {
    value.ir_type == "Integer"
    value.value < 2048
    value.value == [512, 768, 1024, 128][_]
}

# Check if string value indicates weak key size
has_weak_key_size_string(value) {
    value.ir_type == "String"
    regex.match("^(512|768|1024|128)$", value.value)
}

# Check if SSL mode is weak
has_weak_ssl_mode(value) {
    value.ir_type == "String"
    lower := lower(value.value)
    lower == weak_ssl_modes[_]
}

# Check if boolean indicates encryption disabled
encryption_disabled(value) {
    value.ir_type == "Boolean"
    value.value == false
}

# Check if attribute name matches keyword set
matches_keyword_set(name, keywords) {
    lower_name := lower(name)
    keyword := lower(keywords[_])
    contains(lower_name, keyword)
}

# Extract string value from various expression types
get_string_value(expr) = value {
    expr.ir_type == "String"
    value := expr.value
}

get_string_value(expr) = value {
    expr.ir_type == "VariableReference"
    value := expr.value
}

# Check for weak algorithm in attribute
check_weak_encryption_algorithm(attr) {
    matches_keyword_set(attr.name, encryption_key_keywords)
    has_weak_algorithm(attr.value)
}

# Check for weak key size
check_weak_key_size(attr) {
    matches_keyword_set(attr.name, key_size_keywords)
    has_weak_key_size(attr.value)
}

check_weak_key_size(attr) {
    matches_keyword_set(attr.name, key_size_keywords)
    has_weak_key_size_string(attr.value)
}

# Check for weak TLS version
check_weak_tls_version(attr) {
    matches_keyword_set(attr.name, tls_version_keywords)
    has_weak_tls_version(attr.value)
}

# Check for weak cipher suite
check_weak_cipher_suite(attr) {
    matches_keyword_set(attr.name, cipher_suite_keywords)
    has_weak_cipher_pattern(attr.value)
}

# Check for weak certificate/algorithm settings
check_weak_certificate(attr) {
    matches_keyword_set(attr.name, certificate_keywords)
    has_weak_algorithm(attr.value)
}

# Check for disabled/unset storage encryption
check_weak_storage_encryption(attr) {
    matches_keyword_set(attr.name, storage_encryption_keywords)
    attr.name == "encrypted"
    encryption_disabled(attr.value)
}

# Check for weak SSL mode in database
check_weak_database_encryption(attr) {
    matches_keyword_set(attr.name, database_encryption_keywords)
    has_weak_ssl_mode(attr.value)
}

# Check for plaintext secret storage
check_plaintext_secret(attr) {
    matches_keyword_set(attr.name, secret_keywords)
    lower_name := lower(attr.name)
    lower_name == "type"
    attr.value.ir_type == "String"
    lower(attr.value.value) == "String"
}

# Check for weak network encryption
check_weak_network_encryption(attr) {
    matches_keyword_set(attr.name, network_encryption_keywords)
    has_weak_algorithm(attr.value)
}

check_weak_network_encryption(attr) {
    matches_keyword_set(attr.name, network_encryption_keywords)
    attr.name == "ike_version"
    attr.value.ir_type == "String"
    lower(attr.value.value) == "1"
}

# Main rule: Detect weak encryption algorithm selection (CWE-326)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    check_weak_encryption_algorithm(attr)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak or deprecated encryption algorithm. (CWE-326)"
    }
}

