contains_str(str, substr) {
    regex.match(sprintf(".*%s.*", [substr]), str)
}

is_weak_algorithm_exact(s) {
    alg := weak_algorithms[_]
    upper(s) == alg
}

is_weak_algorithm_substring(s) {
    alg := weak_algorithms[_]
    contains_str(upper(s), alg)
}

is_weak_tls_version(s) {
    norm := regex.replace(upper(replace(replace(replace(s, ".", ""), "_", ""), "-", "")), "^V", "")
    version := weak_tls_versions[_]
    norm == version
}

is_weak_cipher_pattern(s) {
    pattern := weak_cipher_patterns[_]
    contains_str(upper(s), pattern)
}

is_weak_key_size(n) {
    n < 2048
    n > 0
}

is_weak_ssl_mode(s) {
    mode := weak_ssl_modes[_]
    lower(s) == mode
}

is_encryption_disabled(b) {
    b == false
}

name_matches_keyword(name, keywords) {
    kw := keywords[_]
    contains_str(lower(name), kw)
}

func_name_is_weak(name) {
    weak_func := weak_func_names[_]
    contains_str(lower(name), weak_func)
}

