package glitch

import data.glitch_lib

weak_algorithms = {"DES", "3DES", "RC4", "RC2", "BLOWFISH", "MD5", "SHA1", "SHA-1", "MD5_CRYPT", "MD5CRYPT"}

weak_tls_versions = {"SSLV2", "SSLV3", "TLSV1", "TLSV1.0", "TLSV1.1", "TLS1.0", "TLS1.1", "SSLV2.0", "SSLV3.0", "TLS10", "TLS11"}

weak_cipher_patterns = {"DES", "RC4", "NULL", "EXPORT", "ANON"}

weak_key_sizes = {512, 768, 1024}

weak_ssl_modes = {"disabled", "preferred", "optional", "false"}

encryption_key_keywords = {"algorithm", "encryption_type", "cipher", "crypto", "cryptographic", "symmetric", "asymmetric", "encrypt", "signature_algorithm", "key_algorithm", "digest", "hash", "checksum"}

key_size_keywords = {"key_size", "key_length", "bits", "modulus", "key_bits", "rsa_key_size", "key_length_bits", "salt_size"}

tls_version_keywords = {"tls_version", "ssl_version", "min_version", "protocol_version", "security_policy", "policy", "ike_version", "ipsec_policy", "vpn_type"}

cipher_suite_keywords = {"cipher_suite", "ciphers", "allowed_ciphers", "ssl_policy", "policy_name", "tls_policy", "cipher_suites", "phase1_integrity_algorithms", "phase2_encryption_algorithms"}

certificate_keywords = {"certificate", "cert", "private_key", "public_key", "key_algorithm", "signature_algorithm"}

storage_encryption_keywords = {"sse_algorithm", "encryption", "encrypted", "kms_key_id", "server_side_encryption", "storage_encrypted", "require_ssl", "ssl_mode", "tls", "enable_advanced"}

secret_keywords = {"type", "secure_string", "key_id", "data_type", "vars_prompt", "encrypt"}

network_encryption_keywords = {"phase1_integrity_algorithms", "phase2_encryption_algorithms", "ike_version", "ipsec_policy", "vpn_type", "cipher_suites"}

sensitive_data_keywords = {"password", "passwd", "secret", "key", "token", "credential", "auth", "private"}

weak_func_names = {"hash", "digest", "md5", "sha1", "sha-1", "checksum", "md5_crypt", "md5crypt", "filter|hash", "filter|md5", "filter|sha1", "filter|sha-1", "filter|checksum"}

contains_str(str, substr) {
    regex.match(sprintf(".*%s.*", [substr]), str)
}

is_weak_algorithm_exact(s) {
    alg := weak_algorithms[_]
    upper(s) == alg
}

is_weak_algorithm_substring(s) {
    alg := weak_algorithms[_]
    contains_str(upper(s), alg)
}

is_weak_tls_version(s) {
    norm := regex.replace(upper(replace(replace(replace(s, ".", ""), "_", ""), "-", "")), "^V", "")
    version := weak_tls_versions[_]
    norm == version
}

is_weak_cipher_pattern(s) {
    pattern := weak_cipher_patterns[_]
    contains_str(upper(s), pattern)
}

is_weak_key_size(n) {
    n < 2048
    n > 0
}

is_weak_ssl_mode(s) {
    mode := weak_ssl_modes[_]
    lower(s) == mode
}

is_encryption_disabled(b) {
    b == false
}

name_matches_keyword(name, keywords) {
    kw := keywords[_]
    contains_str(lower(name), kw)
}

func_name_is_weak(name) {
    weak_func := weak_func_names[_]
    contains_str(lower(name), weak_func)
}

collect_all_strings(node) = result {
    node.ir_type == "String"
    result = {node.value}
}

collect_all_strings(node) = result {
    node.ir_type == "Array"
    result = {s | elem := node.value[_]; strings := collect_all_strings(elem); s := strings[_]}
}

collect_all_strings(node) = result {
    node.ir_type == "Hash"
    key_strings = {s | pair := node.value[_]; ks := collect_all_strings(pair.key); s := ks[_]}
    val_strings = {s | pair := node.value[_]; vs := collect_all_strings(pair.value); s := vs[_]}
    result = key_strings | val_strings
}

collect_all_strings(node) = result {
    node.ir_type == "Access"
    result = collect_all_strings(node.right)
}

collect_all_strings(node) = result {
    node.ir_type == "FunctionCall"
    result = {s | arg := node.args[_]; arg_strs := collect_all_strings(arg); s := arg_strs[_]}
}

collect_all_strings(node) = result {
    node.ir_type == "MethodCall"
    result = {s | arg := node.args[_]; arg_strs := collect_all_strings(arg); s := arg_strs[_]}
}

collect_all_strings(node) = result {
    node.ir_type == "BlockExpr"
    result = {s | stmt := node.statements[_]; stmt_strs := collect_all_strings(stmt); s := stmt_strs[_]}
}

collect_all_strings(node) = result {
    result = set()
}

check_args_contain_weak_algorithm(node) {
    strings := collect_all_strings(node)
    s := strings[_]
    is_weak_algorithm_exact(s)
}

check_args_contain_weak_tls(node) {
    strings := collect_all_strings(node)
    s := strings[_]
    is_weak_tls_version(s)
}

check_args_contain_weak_cipher(node) {
    strings := collect_all_strings(node)
    s := strings[_]
    is_weak_cipher_pattern(s)
}

build_result(element, parent_path, msg) = {
    "type": "sec_weak_crypt",
    "element": element,
    "path": parent_path,
    "description": sprintf("Inadequate Encryption Strength - %s (CWE-326)", [msg])
}

check_value_result(value) = result {
    value.ir_type == "String"
    is_weak_algorithm_exact(value.value)
    result = {"msg": "Use of weak encryption algorithm", "value": value}
}

check_value_result(value) = result {
